local CookwareFounder = {}
local PRODUCTS = {
    simple_iron_skillet = { name = "Preprosta železna ponev", ironCost = 2, time = 3, cost = 35, culinary = 18, happiness = 1, description = "Preprosta železna ponev za kuhinjo." },
    bronze_cauldron = { name = "Bronast kotel", bronzeCost = 2, ironCost = 1, time = 5, cost = 110, culinary = 32, happiness = 1, prestige = 2, description = "Bronast kotel za trgovce." },
    copper_sauce_pan = { name = "Bakreni lonček", copperCost = 2, bronzeCost = 1, ironCost = 1, time = 8, cost = 280, culinary = 48, happiness = 2, prestige = 6, description = "Bakreni lonček za plemiče." },
    silver_lidded_pot = { name = "Srebrnopokrovka lonec", silverCost = 2, copperCost = 1, bronzeCost = 1, ironCost = 1, time = 12, cost = 680, culinary = 62, happiness = 3, prestige = 14, description = "Srebrnopokrovka lonec za visoke plemiče." },
    gold_inlaid_pan = { name = "Zlatovložena ponev", goldCost = 2, silverCost = 1, copperCost = 1, bronzeCost = 1, ironCost = 1, jewelCost = 1, time = 16, cost = 1500, culinary = 78, happiness = 5, prestige = 27, description = "Zlatovložena ponev z draguljem za visoko plemstvo." },
    royal_grand_cookware_set = { name = "Kraljevski veliki kuhinjski set", goldCost = 3, silverCost = 2, copperCost = 1, bronzeCost = 1, ironCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3500, culinary = 92, happiness = 12, prestige = 56, description = "Veliki kraljevski kuhinjski set z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    cookware_workshop = { name = "Kuhinjska posoda delavnica", cost = { gold = 220, wood = 100, stone = 120, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    casting_loft = { name = "Livna podstrešje", cost = { gold = 820, wood = 240, stone = 240, bronze = 6, copper = 6 }, upkeep = 19, qualityBonus = 18 },
    master_founder_atelier = { name = "Mojstrski livarski atelje", cost = { gold = 2400, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_cookware_palace = { name = "Kraljevska kuhinjska palača", cost = { gold = 9800, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
CookwareFounder.ironStock = 14; CookwareFounder.bronzeStock = 12; CookwareFounder.copperStock = 12; CookwareFounder.silverStock = 6; CookwareFounder.goldStock = 6; CookwareFounder.jewelStock = 4; CookwareFounder.pearlStock = 4
CookwareFounder.productStock = {}; CookwareFounder.buildings = {}; CookwareFounder.maker = nil; CookwareFounder.activeMaking = {}; CookwareFounder.totalProducts = 0; CookwareFounder.dayTimer = 0
function CookwareFounder.init() CookwareFounder.ironStock=14; CookwareFounder.bronzeStock=12; CookwareFounder.copperStock=12; CookwareFounder.silverStock=6; CookwareFounder.goldStock=6; CookwareFounder.jewelStock=4; CookwareFounder.pearlStock=4; CookwareFounder.productStock={}; CookwareFounder.buildings={}; CookwareFounder.maker=nil; CookwareFounder.activeMaking={}; CookwareFounder.totalProducts=0; CookwareFounder.dayTimer=0; print("[CookwareFounder] Royal Cookware Founder System initialized (6 products, 4 buildings)") end
function CookwareFounder.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CookwareFounder.maker={name=n or ("Livalec posode "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Livalec posode najet: %s (spretnost: %d)",CookwareFounder.maker.name,s),"success") end; return true end
function CookwareFounder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CookwareFounder.build(id) local ok,e=CookwareFounder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CookwareFounder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CookwareFounder.getQualityBonus() local b=0; for _,bd in ipairs(CookwareFounder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CookwareFounder.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CookwareFounder.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CookwareFounder.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.copperCost and CookwareFounder.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if d.silverCost and CookwareFounder.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CookwareFounder.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CookwareFounder.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CookwareFounder.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CookwareFounder.buildings==0 then return false,"Potrebna kuhinjska posoda delavnica" end; if not CookwareFounder.maker then return false,"Potreben livalec posode" end; return true end
function CookwareFounder.make(pt,qty) qty=qty or 1; local ok,e=CookwareFounder.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CookwareFounder.ironStock=CookwareFounder.ironStock-d.ironCost*qty end; if d.bronzeCost then CookwareFounder.bronzeStock=CookwareFounder.bronzeStock-d.bronzeCost*qty end; if d.copperCost then CookwareFounder.copperStock=CookwareFounder.copperStock-d.copperCost*qty end; if d.silverCost then CookwareFounder.silverStock=CookwareFounder.silverStock-d.silverCost*qty end; if d.goldCost then CookwareFounder.goldStock=CookwareFounder.goldStock-d.goldCost*qty end; if d.jewelCost then CookwareFounder.jewelStock=CookwareFounder.jewelStock-d.jewelCost*qty end; if d.pearlCost then CookwareFounder.pearlStock=CookwareFounder.pearlStock-d.pearlCost*qty end; local t=d.time; if CookwareFounder.maker then t=math.max(1,t-math.floor(CookwareFounder.maker.skill/13)) end; table.insert(CookwareFounder.activeMaking,{id="cookware_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,culinary=d.culinary or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Litje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CookwareFounder.completeMaking(m) local q=1.0+(CookwareFounder.getQualityBonus()/100); if CookwareFounder.maker then q=q+(CookwareFounder.maker.skill/150) end; q=math.min(2.4,q); CookwareFounder.productStock[m.productType]=(CookwareFounder.productStock[m.productType] or 0)+m.quantity; CookwareFounder.totalProducts=CookwareFounder.totalProducts+m.quantity; if m.culinary>0 and _G.state then _G.state.culinary=(_G.state.culinary or 0)+m.culinary end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CookwareFounder.maker then CookwareFounder.maker.itemsMade=CookwareFounder.maker.itemsMade+m.quantity; if math.random()<0.25 then CookwareFounder.maker.skill=math.min(100,CookwareFounder.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Posoda izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cookware.completed",{productName=m.productName,culinary=m.culinary,prestige=m.prestige,happiness=m.happiness}) end end
function CookwareFounder.update(dt) if not _G.state then return end; CookwareFounder.dayTimer=CookwareFounder.dayTimer+dt; if CookwareFounder.dayTimer>=30 then CookwareFounder.dayTimer=0; for i=#CookwareFounder.activeMaking,1,-1 do local m=CookwareFounder.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CookwareFounder.completeMaking(m); table.remove(CookwareFounder.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CookwareFounder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CookwareFounder.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CookwareFounder.getStats() return {ironStock=CookwareFounder.ironStock,bronzeStock=CookwareFounder.bronzeStock,copperStock=CookwareFounder.copperStock,silverStock=CookwareFounder.silverStock,goldStock=CookwareFounder.goldStock,jewelStock=CookwareFounder.jewelStock,pearlStock=CookwareFounder.pearlStock,productStock=CookwareFounder.productStock,numBuildings=#CookwareFounder.buildings,hasMaker=CookwareFounder.maker~=nil,makerName=CookwareFounder.maker and CookwareFounder.maker.name or "—",makerSkill=CookwareFounder.maker and CookwareFounder.maker.skill or 0,activeMaking=#CookwareFounder.activeMaking,totalProducts=CookwareFounder.totalProducts} end
return CookwareFounder
